import hashlib, json

def H(obj) -> str:
    return hashlib.sha256(json.dumps(obj).encode()).hexdigest()

def mbr(points):
    xs = [p[0] for p in points]; ys = [p[1] for p in points]
    return [min(xs), max(xs), min(ys), max(ys)]

def union(rects):
    return [min(r[0] for r in rects), max(r[1] for r in rects),
            min(r[2] for r in rects), max(r[3] for r in rects)]

def intersects(r, q):
    return not (r[1] < q[0] or r[0] > q[1] or r[3] < q[2] or r[2] > q[3])

def inside(p, q):
    return q[0] <= p[0] <= q[1] and q[2] <= p[1] <= q[3]

# Nodo foglia: {"leaf": [punti]}; nodo interno: {"children": [nodi]}
def digest(node):
    """Restituisce (rettangolo, hash) del nodo."""
    if "leaf" in node:
        return mbr(node["leaf"]), H(["L", node["leaf"]])
    entries = [digest(c) for c in node["children"]]
    return union([e[0] for e in entries]), H(["I", entries])

leaves = [{"leaf": [[1, 8], [2, 3], [2, 4]]}, {"leaf": [[3, 4], [5, 3], [5, 4]]},
          {"leaf": [[5, 5], [6, 3], [6, 5]]}, {"leaf": [[7, 2], [8, 12]]}]
tree = {"children": [{"children": leaves[:3]}, {"children": leaves[3:]}]}
root_rect, root_hash = digest(tree)          # root_hash va nell'header (IndexHash)

def query(node, q):
    """Prover: restituisce il VO."""
    rect, h = digest(node)
    if not intersects(rect, q):
        return {"pruned": [rect, h]}
    if "leaf" in node:
        return {"leaf": node["leaf"]}
    return {"children": [query(c, q) for c in node["children"]]}

def verify(vo, q):
    """Verifier: ricostruisce (rett, hash) e raccoglie i risultati."""
    if "pruned" in vo:
        rect, h = vo["pruned"]
        if intersects(rect, q):
            raise ValueError("sottoalbero scartato ma interseca la query")
        return rect, h, []
    if "leaf" in vo:
        pts = vo["leaf"]
        return mbr(pts), H(["L", pts]), [p for p in pts if inside(p, q)]
    parts = [verify(c, q) for c in vo["children"]]
    entries = [[r, h] for r, h, _ in parts]
    res = [p for _, _, rs in parts for p in rs]
    return union([e[0] for e in entries]), H(["I", entries]), res

q = [4, 6, 4, 6]
vo = query(tree, q)
_, h, res = verify(vo, q)
print("risultato:", res, "| radice ok:", h == root_hash)

# prover disonesto: toglie (6,5) dalla foglia visitata
bad = json.loads(json.dumps(vo))
bad["children"][0]["children"][2]["leaf"].remove([6, 5])
_, h2, res2 = verify(bad, q)
print("risultato truffa:", res2, "| radice ok:", h2 == root_hash)

# prover disonesto: dichiara 'pruned' il terzo figlio con un rettangolo falso
bad2 = json.loads(json.dumps(vo))
_, h3 = digest(leaves[2])
bad2["children"][0]["children"][2] = {"pruned": [[9, 9, 9, 9], h3]}
_, h4, res4 = verify(bad2, q)
print("risultato truffa 2:", res4, "| radice ok:", h4 == root_hash)
